function Header({ cart }) {
  const total = cart.reduce((sum, item) => sum + item.quantity, 0);

  return (
    <div className="header">
      <div>📱 BAPhone</div>
      <div>🛒 Giỏ hàng ({total})</div>
    </div>
  );
}

export default Header;
